SELECT id, order_id, AVG(amount) OVER (PARTITION BY method ORDER BY paid_at, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_avg_amount, MAX(amount) OVER (PARTITION BY method ORDER BY paid_at, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_max_amount, SUM(amount) OVER (PARTITION BY method ORDER BY paid_at, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_sum_amount FROM payments
